func:
// 1. Verificamos si la orden viene explícitamente del botón reiniciar
if (msg.topic === "reiniciar") {
    // Vaciamos el historial en la memoria global
    flow.set("historial_bitacora", []);

    // Devolvemos un array vacío para que el template limpie la pantalla de inmediato
    msg.payload = [];
    return msg;
}

// 2. Si la orden viene del botón guardar (o cualquier otro flujo normal):
let historial = flow.get("historial_bitacora") || [];

// Leemos los valores actuales de las cajas de texto de la interfaz
let nombreActual = flow.get("ui_nombre_input") || "Sin registrar";
let turnoActual = flow.get("ui_turno_input") || "Matutino";

// Generamos la fecha y hora exacta del registro
let ahora = new Date();
let fechaHoraFormateada = ahora.toLocaleString();

// Creamos el nuevo objeto de registro
let nuevoRegistro = {
    timestamp: fechaHoraFormateada,
    operador: nombreActual,
    turno: turnoActual,
    lugar: "Xalapa, Ver. (Estación Principal)",
    nivelRef: msg.payload.nivel_tanque_porcentaje || 0
};

// Agregamos el registro al inicio del historial
historial.unshift(nuevoRegistro); 

// Límite de seguridad para no saturar memoria
if (historial.length > 50) {
    historial.pop();
}

// Guardamos el historial actualizado en la memoria global
flow.set("historial_bitacora", historial);

// Enviamos el historial completo al template de la derecha
msg.payload = historial;

return msg;

// 1. Vaciamos por completo el historial guardado en la memoria global
flow.set("historial_bitacora", []);

// 2. Limpiamos la variable temporal del nombre para que no se quede guardada la anterior
flow.set("ui_nombre_input", "Sin registrar");

// 3. Enviamos un arreglo vacío directamente al template para que limpie la pantalla al instante
msg.payload = [];

return msg;

let estado = msg.payload.actuadores ? msg.payload.actuadores.lampara_piloto : false;
msg.payload = {
    estadoTexto: estado ? "LÁMPARA PILOTO: ENCENDIDA" : "LÁMPARA PILOTO: APAGADA",
    colorLed: estado ? "#ff0000" : "#555555" // Rojo si prende, gris si apaga
};
return msg;

let estado = msg.payload.actuadores ? msg.payload.actuadores.bomba_principal : false;

msg.payload = {
    estadoTexto: estado ? "BOMBA PRINCIPAL: ACTIVA" : "BOMBA PRINCIPAL: APAGADA",
    colorLed: estado ? "#00ff00" : "#555555"
};

return msg;

let estado = msg.payload.actuadores ? msg.payload.actuadores.bomba_respaldo : false;
msg.payload = {
    estadoTexto: estado ? "BOMBA RESPALDO: ACTIVA" : "BOMBA RESPALDO: APAGADA",
    colorLed: estado ? "#ffaa00" : "#555555" // Naranja si prende, gris si apaga
};
return msg;

let nivel = msg.payload.nivel_tanque_porcentaje || 0;
msg.payload = nivel;
return msg;

// 1. Extraemos los valores del payload que envía el sensor DHT22
let temp = msg.payload.temperatura || 0;
let hum = msg.payload.humedad || 0;

// 2. Preparamos el mensaje para la Temperatura (Salida 1)
let msgTemp = {
    payload: temp,
    topic: "Temperatura"
};

// 3. Preparamos el mensaje para la Humedad (Salida 2)
let msgHum = {
    payload: hum,
    topic: "Humedad"
};

// 4. Retornamos ambos mensajes en un array para las dos salidas del nodo
return [msgTemp, msgHum];

// 1. Obtenemos el ángulo que seleccionó el operador en el slider (0 a 180)
let angulo = msg.payload;

// 2. Preparamos el mensaje en formato JSON para enviarlo a la ESP32 (por MQTT o Serial)
msg.payload = {
    servo_valvula: angulo
};

// Opcional: Definimos el topic si usas MQTT
msg.topic = "esp32/servo/control";

return msg;

// 1. Obtenemos los valores que llegan de la entrada
let temperatura = msg.payload.temperatura || 0;
let nivelTanque = msg.payload.nivel || 0;

let limiteTemperatura = 40.0; 
let limiteNivel = 90.0;       

let textoEstado = "🟢 Sistema Operando con Normalidad (Seguro)";

// 2. Evaluamos la condición de peligro
if (temperatura >= limiteTemperatura || nivelTanque >= limiteNivel) {
    textoEstado = "🔴 ¡PELIGRO: Temperatura o Nivel Crítico Excedido!";
}

// 3. Enviamos únicamente el texto como payload para el nodo de texto
msg.payload = textoEstado;

return msg;
